INSERT INTO himnos (id, title, description, musical_note, paragraphs, chorus, filename)
VALUES
('128215b2-0894-4d2d-90fe-4daf172e0123', $a$Doxologia (Judas 24-25)$a$, $a$DOXOLOGÍA   (JUDAS 1:24-25)...$a$, $a$--$a$, $a$[{"paragraph": "DOXOLOGÍA \n (JUDAS 1:24-25)"}, {"paragraph": "/Y aquel que es poderoso para guardaros,  \n para guardaros sin caída,  \n y presentaros sin mancha delante de Su gloria,  \n con gran alegría./"}, {"paragraph": "/Al único y sabio Dios nuestro salvador, \n  sea gloria y majestad, imperio y potencia,  \n ahora y por todos los siglos. \n Amén./"}, {"paragraph": "/Aaaamén, \n Aaaamen, \n ahora y por todos los siglos. \n Amén./"}]$a$::jsonb, $a$[]$a$::jsonb, $a$Doxologia (Judas 24-25).json$a$),
('0d4e00e0-50c3-4e76-8c4b-25fcf07d7d95', $a$DIOS ETERNO$a$, $a$MIL VECES TE FALLE , MAS TU FUIST...$a$, $a$--$a$, $a$[{"paragraph": "MIL VECES TE FALLE , MAS TU FUISTE FIEL TU GRACIA ME LEVANTO, ME BASTA TU AMOR  \n DIOS ETERNO TU LUZ POR SIEMPRE BRILLARA  \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "DIOS ETERNO TU LUZ  \n POR SIMPRE BRILLARA  \n EN TU GLORIA INCOMPARABLE  \n SIN FINAL \n Y EL CLAMOR DE MI SER  \n \tES POR TI TE DOY MI ALMA"}, {"paragraph": "SEÑOR TU VOLUNTAD PERMANECERÁ  \n EN TI ME QUIERO PERDER EN ADORACION  \n DIOS ETERNO TU LUZ SIMEPRE BRILLARA \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "DE MI CORAZON DE DOY EL CONTROL  \n CONSUME TODO MI INTERIOR, DIOS  \n TU JUSTICIA Y AMOR ME ABRAZA SEÑOR  \n TE AMO DESDE MII NTERIOR"}, {"paragraph": "DIOS ETERNO TU LUZ POR SIMPRE BRILLARA  \n EN TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "EN MI CORAZON TE DOY EL CONTROL CONSUME TODO MI NTERTIO R \n JUSTICIA Y AMOR ME ABRAZA SELO DESDE MI INTERIOR"}]$a$::jsonb, $a$[]$a$::jsonb, $a$DIOS ETERNO.json$a$),
('aa689176-6baa-474d-87da-e172aa845578', $a$alabare$a$, $a$//ALABARE, ALABARE//    ALABARE A...$a$, $a$--$a$, $a$[{"paragraph": "//ALABARE, ALABARE//  \n ALABARE A MI SEÑOR \n JUAN VIO EL NUMERO DE LOS REDIMIDOS"}, {"paragraph": "Y TODOS ALABABAN  AL SEÑOR  \n UNOS ORABAN Y OTROS CANTABAN  \n Y TODOS ALABABAN AL SEÑOR."}]$a$::jsonb, $a$[]$a$::jsonb, $a$alabare.json$a$),
('a4d29ce1-389b-361f-0149-732bc9ce7b53', $a$EL SEÑOR ES MI PASTOR$a$, $a$El Señor es mi pastor Nada a mí me faltara En su$a$, $a$A|La$a$, $a$[{"id": "7886103f-da7d-5d09-217b-a4ab1497db6d", "paragraph": "El Señor es mi pastor\nNada a mí me faltara\nEn sus verdes pastos\nMe hace descansar\n\nDe sus aguas me dará\nMi alma el restaurara\nPor senderos de justicia me guiara\nPor amor de su nombre", "chorusPos": [[1]]}, {"id": "6f008a88-e495-421e-cf58-6d96ea2d83e6", "paragraph": "El Señor es mi pastor\nNo hay razón para el temor\nPues su vara me da aliento y protección\n\nSi en el valle de aflicción\nMe rodea la opresión\nEl conmigo esta y bendecido soy\nPor amor de su nombre", "chorusPos": [[1]]}, {"id": "dc36e5fe-3fcc-7682-2672-f7699d45878f", "paragraph": "//Misericordia y bien me seguirán\nTu plenitud me saciara\nEn tu morada por la eternidad//", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Jamás me dejaras\nEn tu fidelidad, Jesús\nConfiado esta mi corazón\n\nDe ti dependeré\nTu voz escuchare, Jesús\nTe seguiré, mi buen pastor", "id": "c42c8f89-422f-a4ea-6fef-7dddf58d51f3"}]$a$::jsonb, $a$EL SEÑOR ES MI PASTOR.json$a$),
('ee3b9120-e614-4fa3-8a26-7402ceef67e6', $a$EL  GOZO QUE TENGO YO$a$, $a$EL  GOZO QUE TENGO YO    /EL MUND...$a$, $a$--$a$, $a$[{"paragraph": "EL  GOZO QUE TENGO YO  \n /EL MUNDO NO ME LO DIO/ COMO NO ME LO DIO  \n NO ME LO PUEDE QUITAR \n SI EMPEZAMOS A ORAR"}, {"paragraph": "SI EMPEZAMOS A ORAR \n CLAMAREMOS A JEHOVA  \n SI EMPEZAMOS A ORAR  \n ESTE MUNDO TIEMBLA \n ELIAS ORO EL FUEGO CAYO \n ORO JOSUE EL SOL SE PARO"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EL  GOZO QUE TENGO YO.json$a$),
('e04bcad5-e281-4676-aa83-47ffb1115b5f', $a$Amigos-Daniel Calveti$a$, $a$DESDE CHICOS APRENDIMOS, AL QUERE...$a$, $a$--$a$, $a$[{"paragraph": "DESDE CHICOS APRENDIMOS, AL QUERERNOS COMO HERMANOS, \n EL FUTBOL Y LAS CANICAS, A LOS BUENOS Y A LOS MALOS"}, {"paragraph": "MUCHAS VECES NOS PELEAMOS, OTRAS VECES NI HABLAMOS, \n PERO AUN SIGO SIENDO AMIGO, DEL QUE ES COMO MI HERMANO."}, {"paragraph": "AMIGO TU, AMIGO YO \n PERDONAME SI TE HE FALLADO, \n LO SE MUY BIEN, \n  LO SABES TÚ,  \n QUIERO ESTAR Y COMPARTIR,"}, {"paragraph": "MOMENTOS BUENOS Y LOS MALOS, \n QUIERO REIR, TAL VEZ LLORAR, \n AMIGOS QUE.....NUNCA OLVIDAMOS."}, {"paragraph": "EN MOMENTOS PRESENTIMOS, QUE SOLOS NOS ENCONTRAMOS,  \n ES ALLÍ DONDE APARECEN, LOS QUE SON MAS QUE HERMANOS."}, {"paragraph": "LOS REGALITOS QUE NOS DAMOS,  \n LAS PALABRAS QUE CALLAMOS, \n LOS ABRAZOS QUE NEGAMOS, AL QUE HOY NO ESTÁ A TU LADO,"}, {"paragraph": "PERO AUN AFUERA HAY MUCHOS, ESPERANDO DE UN ABRAZO, \n NECESITAN DE AQUEL, QUE SE A DE LLAMAR HERMANO."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Amigos-Daniel Calveti.json$a$),
('31c48d6e-d35d-4e7c-85fa-c807e88e4adb', $a$ALGO ESTA CAYENDO AQUÍ$a$, $a$ALGO ESTA CAYENDO AQUÍ   ALGO EST...$a$, $a$--$a$, $a$[{"paragraph": "ALGO ESTA CAYENDO AQUÍ \n ALGO ESTA CAYENDO AQUÍ \n ES TAN FUERTE SOBRE MI \n MIS MANOS LEVANTARÉ \n Y SU GLORIA TOCARÉ"}, {"paragraph": "ESTA CAYENDO \n SU GLORIA SOBRE MI \n SANANDO HERIDAS \n LEVANTANDO AL CAIDO \n SU GLORIA ESTÁ AQUÍ \n SU GLORIA ESTA AQUÍ"}, {"paragraph": "LEVANTO MIS MANOS \n LEVANTO MIS MANOS \n AUNQUE NO TENGA FUERZAS \n LEVANTO MIS MANOS \n AUNQUE TENGA MIL PROBLEMAS"}, {"paragraph": "CUANDO LEVANTO MIS MANOS \n COMIENZO A SENTIR \n UNA UNCIÓN QUE ME HACE CANTAR \n CUANDO LEVANTO MIS MANOS \n COMIENZO A SENTIR  \n EL FUEGO"}, {"paragraph": "CUANDO LEVANTO MIS MANOS \n MIS CARGAS SE VAN \n NUEVAS FUERZAS TU ME DAS \n TODO ESO ES POSIBLE \n TODO ESO ES POSIBLE \n CUANDO LEVANTO MIS MANOS"}, {"paragraph": "FUENTE DE VIDA \n SEPARADO DE TI... NO SOY NADA \n ALEJADO DE TI.. MUERO \n SI TU NO ESTAS EN MI YO DESESPERO \n PIERDO LA ESPERANZA \n MUERE EL ANHELO"}, {"paragraph": "COMO VOY ALEJARME DE TI  \n FUENTE DE VIDA \n TU ME DISTE LA ALEGRIA \n COMO VOY A SEPARARME DE TI  \n MI DIOS Y MI GUIA \n SI SOLO TU TIENES PALABRAS..  \n DE VIDA"}, {"paragraph": "PRECIOSO JESUS \n AL CONTEMPLAR TU OBRA EN LA CRUZ \n TANTO AMAR DERRAMADO \n Y TODO POR MI \n CON GRATITUD ME QUIERO ACERCAR \n SOLO TENGO MI VIDA ....ACEPTALA"}, {"paragraph": "NO SE COMO EXPRESARME ANTE TU HERMOSURA \n RODEADA DE GLORIA Y PODER \n NECESITO DECIRTE  \n LO QUE SIENTO AHORA \n ME ACERCO A TI.. AL SANTO LUGAR"}, {"paragraph": "PRECIOSO JESUS, MI REDENTOR \n AMADO SEÑOR, ERES TODO PARA MI \n TE ADORARE CADA DIA DE MI VIDA \n NO PUEDO VIVIR SI NO ESTAS JUNTO A MI"}, {"paragraph": "BENDITO SEÑOR \n POR TI ES MI CLAMOR \n Y SIN NINGUN TEMOR \n EN TI PUEDO CONFIAR \n BENDITO JESUS"}, {"paragraph": "HOY PUEDO ESCUCHAR \n TU VOZ DE SANIDAD \n RESTAURANDO MI SER \n BENDITO JESUS"}, {"paragraph": "MI DESEO ERES TU \n MI MOMENTO MI AMOR \n LA ALEGRIA DE VIVIR \n BENDITO JESUS"}, {"paragraph": "ERES MI FUENTE DE AMOR \n ERES AIRE ERES SOL \n EL LATIDO  DE MI CORAZON  \n BENDITO JESUS \n BENDITO AMOR DE MI SEÑOR"}, {"paragraph": "TU GRACIA Y FAVOR \n CONTIGO PUEDO VER \n LLENANDO HOY MNI SER \n BENDITO JESUS"}, {"paragraph": "Y HOY TU VOLUNTAD  \n SE RINDE A TU VERDAD \n TU AMOR Y TU BONDAD \n BENDITO JESUS"}, {"paragraph": "DIGNO Y SANTO \n DIGNO ES EL \n CORDERO SANTO \n SANTO, SANTO, ES ÉL"}, {"paragraph": "LEVANTAMOS  \n NUESTRA ALABANZA \n AL QUE EN EL TRONO ESTÁ"}, {"paragraph": "SANTO, SANTO, SANTO, \n DIOS TODOPODERESO \n QUIEN FUE, QUIEN ES  \n Y QUIEN VENDRA \n LA CREQACION TE CANTA  \n Y DAMOS GLORIA A ÉL \n TU ERES DIGNO  \n POR SIEMPRE Y SIEMPRE"}, {"paragraph": "CUENTA CONMIGO \n Y A TRAVES DE LAS  \n GENERACIONES \n VIVIENDO DIFERENTES SITUACIONES \n TUS HIJOS  \n HAN LLEVADO TU PALABRA  \n A PUEBLOS CIUDADES Y NACIONES"}, {"paragraph": "ALGUNOS HAN DADO  \n SU PROPIA VIDA \n Y OTROS VIVEN  \n LEJOS DE SU FAMILIA \n TAMBIEN HAY DE LOS QUE  \n LO HAN DEJADO TODO \n PARA QUE SEPAN QUE TU JESUS \n  ERES LA ALTERNATIVA"}, {"paragraph": "Y YO NO SE SI MI SITUACION  \n SERA DIFICIL O MAS FACIL \n PERO JESUS YO TE DIGO HOY \n CUENTA CONMIGO,  \n PARA ALCANZAR ESTA GENERACION \n CUENTA CONMIGO  \n ME PERTENECE ESTA GENERACION"}]$a$::jsonb, $a$[]$a$::jsonb, $a$ALGO ESTA CAYENDO AQUÍ.json$a$),
('6b057cc9-e01b-407d-afe3-035155bda949', $a$EN LA CRUZ DE JESUS$a$, $a$En el monte calvario estaba una c...$a$, $a$--$a$, $a$[{"paragraph": "En el monte calvario estaba una cruz, \n Emblema de afrenta y dolor; \n Mas yo amo esa cruz do murió mi Jesús. \n Por salvar al más vil pecador."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "Y aunque el mundo desprecie \n La cruz de Jesús, para mi tiene \n Suma atracción; pues en ella llevo \n El cordero de Dios de mi alma la Condenación."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "En la cruz de Jesús do su sangre vertió, \n Hermosura contemplo sin par; \n Pues en ella triunfante a la muerte venció \n Y me ser puede santificar."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}, {"paragraph": "Para siempre su gloria veré \n Sus desprecios con el llevare, y algún \n Día feliz con los santos en luz \n Yo seré siempre fiel a la cruz de Jesús."}, {"paragraph": "¡Oh!, yo siempre amare esa cruz: \n Mi corona Jesús me dará. \n Y algún día en vez de una cruz, \n Que en sus triunfos mi gloria será;"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EN LA CRUZ DE JESUS.json$a$),
('ed8a2c7f-802c-403c-89bc-28af26951347', $a$EN LA CRUZ N.322$a$, $a$Me hirió el pecado, fui a Jesús, ...$a$, $a$--$a$, $a$[{"paragraph": "Me hirió el pecado, fui a Jesús, \n Mostréle mi dolor. \n Perdido errante vi su luz, \n Bendíjome en su amor"}, {"paragraph": "En la cruz, en la cruz, do primero ví la luz,  \n Y las manchas de mi alma, Él lavó \n Fui allí por la fe do ví a Jesús \n  y siempre feliz con Él seré"}, {"paragraph": "Venció la muerte con poder \n Y el padre lo exalto \n Confiar en cristo es mi placer  \n morir no temo yo."}, {"paragraph": "En la cruz en la cruz do primero vi la luz  \n Y las manchas de mi alma el lavo \n Fui ahí por la fe do vi a Jesús \n  y siempre feliz con el seré"}, {"paragraph": "Aunque el se fue conmigo esta  \n el gran consolador \n Divino espíritu que hoy  \n me da perfecto amor"}, {"paragraph": "En la cruz en la cruz do primero vi la luz  \n Y las manchas de mi alma el lavo \n Fui ahí por la fe do vi a Jesús \n  y siempre feliz con el seré"}]$a$::jsonb, $a$[]$a$::jsonb, $a$EN LA CRUZ N.322.json$a$),
('10d45d36-aa2f-9875-fd84-0772644bff46', $a$LA GLORIA DE LA CRUZ$a$, $a$¿Cómo es que en Su perfecto plan mi pecado perdo$a$, $a$E|Mi$a$, $a$[{"id": "9817217a-a0f4-f395-4b5c-2c353b6348a9", "paragraph": "¿Cómo es que en Su perfecto\nplan mi pecado perdonó,\ncuando al morir mi culpa,\n¿el Cordero la llevó?", "chorusPos": [[0]]}, {"id": "fd03b4b7-7f1d-c2e2-8513-f5ef2a765ace", "paragraph": "¿Cuán Sabio y Soberano Dios\nSu gloria mostrará,\ncuando en Su trono,\nel pecador se regocijará?", "chorusPos": [[1]]}, {"id": "b6041dc2-dd4f-866a-8032-71403bec68be", "paragraph": "Qué rectitud Él reveló,\nlibrando al pecador,\ny al culpable perdonó,\nsus manchas Él lavó.", "chorusPos": [[0]]}, {"id": "27a0a508-b0d7-c295-e862-cee0d504e360", "paragraph": "Tu sacrificio propició,\nla ira del Señor,\ny por tu muerte y expiación,\nhoy tengo redención.", "chorusPos": [[1]]}, {"id": "e5b1c0fd-857c-e902-d820-35e2d4fb5d12", "paragraph": "Que gracia para aquellos que,\nhabrían de creer,\namor inagotable que\nno puedo comprende", "chorusPos": [[0]]}, {"id": "7e72a0eb-4286-d6d2-e6c1-2ce3c6f5b63f", "paragraph": "La gracia que me perdonó,\nTu hijo ahora soy\nAmado por la eternidad\nPor lo que hiciste oh Dios", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Oh, la Gloria de la Cruz,\nTu Hijo enviaste a morir.\nMi vida dejaré atrás, para conocer\nla gloria de, la gloria de la cruz.", "id": "e9b35b98-748a-3638-044e-c1582a48bff1"}]$a$::jsonb, $a$LA GLORIA DE LA CRUZ.json$a$),
('3b1aef0f-ea4d-ed4b-c29d-4163acf18ab7', $a$MIENTRAS TENGA ALIENTO$a$, $a$Como agradezco Señor Tomaste en la cruz mi lugar$a$, $a$_$a$, $a$[{"id": "9687c573-42ef-ac05-06d8-75e13c0ff8a3", "paragraph": "Como agradezco Señor\nTomaste en la cruz mi lugar.\nComo agradezco Señor\nTu gran amor y bondades.\nPor acercarme a ti, por permitirme oír,\ny abrir mi corazón al evangelio.", "chorusPos": [[1]]}, {"id": "4ff29b1d-bf63-650e-0304-3c78a4319baa", "paragraph": "Como agradezco Señor\npor tanto, amor en tus ojos.\ncomo agradezco Señor\nel cambio que has hecho en mí.\npor darme tu poder, tu gozo y tu favor,\ny permitirme ver tus bondades.", "chorusPos": [[1]]}, {"id": "78c3ceaa-4765-4960-4ee3-c55ac0fe031e", "paragraph": "Como agradezco Señor\nTomaste en la cruz mi lugar.\nComo agradezco Señor\nTu gran amor y bondades.\nPor acercarme a ti, por permitirme oír,\ny abrir mi corazón al evangelio.", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "//Mientras tenga aliento te alabare,\nMientras viva te cantare,\nMientras lata mi corazón te bendeciré//.", "id": "e25f4560-6615-6f78-aa67-28aafc1360d7"}]$a$::jsonb, $a$MIENTRAS TENGA ALIENTO.json$a$),
('a5ccbbcf-700b-466c-807f-c19e97d72f70', $a$GRANDE, PODEROSO,!OH! DIOS TU$a$, $a$TE ALABARE,DANDO UNA VUELTA TE EX...$a$, $a$--$a$, $a$[{"paragraph": "TE ALABARE,DANDO UNA VUELTA TE EXALTARE,ALSANDO MIS MANOS TU NOMBRE ALABARE SIEMPRE"}, {"paragraph": "POR QUE TU JEHOVA  ME HAS LIBRADO DE TODO MAL, DESATASTE MIS SILICIOS ME SEÑISTE DE VERDAD \n HOY TU NOMBRE JESUS.. ALABARE SIEMPRE"}]$a$::jsonb, $a$[]$a$::jsonb, $a$GRANDE, PODEROSO,!OH! DIOS TU.json$a$),
('f4669fbe-9086-7577-a64d-87d181bdabab', $a$NO HAY OTRO$a$, $a$Un pueblo que nunca se postran Que no se conform$a$, $a$C|Do$a$, $a$[{"id": "d801b2a1-b19f-1b0e-257f-d4dd82e66ffb", "paragraph": "Un pueblo que nunca se postran\nQue no se conforman al mundo y su placer.\n\nUn pueblo de vida consagrada\nY corazón que busca tu gloria conocer.", "chorusPos": [[0]]}, {"id": "13d1383e-5db9-42bd-8504-bd66157a9a72", "paragraph": "Un pueblo creen tu palabra llenos de valor\nY profunda convicción\n\nUn pueblo firmes en la roca que tu\nVerdad proclaman con gran pasión", "chorusPos": [[1]]}, {"id": "27a86c81-fa06-b28b-5820-64f279d3ef7d", "paragraph": "Fieles discípulos de Cristo\nQue al reino de los cielos le dieron su lealtad\n\nSiervos que ante él se postran\nY por el evangelio su vida dan", "chorusPos": [[1]]}, {"id": "30bd6de1-f207-cd4f-59fb-bd97098d72b2", "paragraph": "/Mueve hoy Señor nuestro corazón\nHazlo atento a tu verdad...\nVen renuévanos y confórmanos\nPara hacer tu voluntad/", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Confesamos que tú eres nuestro Dios\nNo hay otro, no hay otro\nSeguiremos el llamado de tu voz\nNo hay otro, no hay otro", "id": "ffc4adc1-3d47-82b3-7dfd-9f66acdccd3c"}, {"choir": "/Confesamos que tú eres nuestro Dios\nNo hay otro, no hay otro\nSeguiremos el llamado de tu voz\nNo hay otro, no hay otro./", "id": "0b99dbf9-2b84-f767-c9c3-8fae68343afe"}]$a$::jsonb, $a$NO HAY OTRO.json$a$),
('dce16c12-d672-87e1-fa88-ad3f80083d4f', $a$ES EXALTADO$a$, $a$Es exaltado en lo alto exaltado es el Rey. Le al$a$, $a$A|La$a$, $a$[{"id": "08375bfb-c1bc-e85d-046b-ca02396ea829", "paragraph": "Es exaltado en lo alto exaltado es el Rey.\nLe alabaré.\nEs exaltado por siempre exaltado\nY yo le alabaré.", "chorusPos": [[1]]}, {"id": "532ff07c-6a0b-caa8-4872-155aa8ec7972", "paragraph": "Majestad, te adoro majestad\nDoy a Cristo toda gloria alabanza y honor.\nMajestad, reino y autoridad.\nDesde tu trono fluye por siempre tu majestad.", "chorusPos": [[2]]}, {"id": "9c0f11dc-11eb-ea6c-efe7-febb09ca7596", "paragraph": "", "chorusPos": [[1], [2]]}]$a$::jsonb, $a$[{"choir": "Él es Señor, por siempre reinarás\nSu creación en él se gozará\n//Es exaltado en lo alto exaltado es el Rey//", "id": "b91c7d8f-0f2c-bf5c-4244-5a2e1a1b27ff"}, {"choir": "Alabad y exaltad el nombre de Cristo\nMagnificad y glorificad a Cristo el Rey.\nMajestad, te adoro majestad,\n//Aquel que murió y resucitó es Rey mi Señor//", "id": "d05a64dc-9314-36cb-cf48-acdc8ca74ca8"}]$a$::jsonb, $a$ES EXALTADO.json$a$),
('b7c4c48f-0e09-4e03-910d-3f581eaca3f9', $a$DALE PALMAS,$a$, $a$DALE PALMAS,   OTRA VEZ,   AL SEÑ...$a$, $a$--$a$, $a$[{"paragraph": "DALE PALMAS, \n OTRA VEZ, \n AL SEÑOR LE SATISFACE, \n DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA PELLISCON \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}, {"paragraph": "ALLI DONDE ESTAS PARADO \n MIRA QUIEN ESTA A TU LADO \n  DALE UNA SONRISITA \n AL SEÑOR LE SATISFACE DALE PALMAS"}]$a$::jsonb, $a$[]$a$::jsonb, $a$DALE PALMAS,.json$a$),
('e19368f7-e87a-4f48-a251-910186b359e9', $a$CONTENDAMOS N. 90$a$, $a$Contendamos, jóvenes por la fe   ...$a$, $a$--$a$, $a$[{"paragraph": "Contendamos, jóvenes por la fe \n Aunque brance el mundo con satanás; \n En la lucha nunca nos vencerán, \n Pues Jesús nos guardará."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}, {"paragraph": "No seamos tibios de Corazón, \n Ni dejemos nunca el primer amor; \n Mantengamos firme la profesión \n De la fe en Salvador."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}, {"paragraph": "Procuremos todos la santidad, \n Sin la cual ninguno verá al Señor; \n Gozo, Paz y eterna felicidad \n Cristo ofrece  al vencedor."}, {"paragraph": "Si sufrimos aquí, reinaremos alli \n En la gloria celestial. \n Si llevamos la cruz por amor de Jesús \n La corona El nos dará"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CONTENDAMOS N. 90.json$a$),
('78584873-d702-0489-5ac1-7dffae419280', $a$SOLO EN JESÚS$a$, $a$Solo en Jesús esta mi fe, mi esperanza y mi canc$a$, $a$D|Re$a$, $a$[{"id": "8013ccb8-8aa5-bfe8-9755-5e7c28b1c199", "paragraph": "Solo en Jesús esta mi fe,\nmi esperanza y mi canción.\nPiedra angular firme y sostén\ninconmovible en la aflicción.", "chorusPos": [[1]]}, {"id": "03be6167-b2bb-5818-6952-d2b5063bad1b", "paragraph": "Solo en Jesús hijo de Dios\nquien se humilló por nuestro bien.\nCordero de mi salvación\npor este mundo herido fue.", "chorusPos": [[2]]}, {"id": "56e731fb-42ed-52a5-f611-1320aa05cc09", "paragraph": "En un sepulcro el yació,\nel cuerpo inerte del Señor.\nMas el tercer día llegó\nresucitó en gloriosa luz", "chorusPos": [[3]]}, {"id": "a3362ff4-b58c-4f11-22f0-ba653dcef9f2", "paragraph": "Desde al nacer hasta el morir\nSea el poder de Cristo en mi.\nNo temeré seguro estoy\nmi vida yo a Él le doy.", "chorusPos": [[4]]}]$a$::jsonb, $a$[{"choir": "Cuán grande amor inmensa paz\nen el temor o adversidad.\nConsolador amigo fiel\nyo en su amor me sostendré.", "id": "fa7bd1e4-2c1a-8d4f-3e65-e69e84fb12c7"}, {"choir": "En una cruz fue a morir\nY Dios mostro su gracia ahí\npues mi pecado Él llevo\nen su aflicción vida me dio.", "id": "a711861c-e1ce-c161-a705-2a2f72bf684b"}, {"choir": "Y al triunfar sobre el mal\nperdió el pecado potestad\nDe Él suyo soy, Él mío es.\nPues con su sangre me compró.", "id": "077f0028-b478-ad3f-8704-37ee6275b796"}, {"choir": "/Ningún poder ningún afán\nde Él me arrebatara.\nHasta que Él venga otra vez\nen su poder me sostendré/.", "id": "d7bd9ecd-e406-d661-17b4-323ed0eba145"}]$a$::jsonb, $a$SOLO EN JESÚS.json$a$),
('074c0c32-3523-fa44-a7a1-4c18c66e87ee', $a$MIRAD CUAL AMOR$a$, $a$Mirad cual amor nos ha dado el Padre al hacernos$a$, $a$A|La$a$, $a$[{"id": "2d026d1f-9e05-b82a-bbc2-b944a487f0c9", "paragraph": "Mirad cual amor\nnos ha dado el Padre\nal hacernos\nhijos de Dios", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "///Para ser llamados\nhijos de Dios///", "id": "bae4fe9f-b3df-1ab0-c324-3460c679e700"}]$a$::jsonb, $a$MIRAD CUAL AMOR.json$a$),
('ea94fd3c-52d5-4c38-93d2-753bf402e1a3', $a$COMO NO CANTARTE SEÑOR$a$, $a$COMO NO CANTARTE SEÑOR   COMO NO ...$a$, $a$--$a$, $a$[{"paragraph": "COMO NO CANTARTE SEÑOR \n COMO NO ALABARTE MI REY \n COMO NO DECIRTE QUE TE AMO \n SI ESTOY ENAMORADO DE  TI"}, {"paragraph": "ES POR ESO QUE YO TE ALABO \n Y ES POR ESO QUE TE SIRVO"}, {"paragraph": "COMO NO GOZARME SEÑOR \n COMO NO ALEGRARME  \n MI REY \n Y CUANDO PERDIDO  \n YO ESTABA \n SOLO TU ME AMASTE JESUS"}]$a$::jsonb, $a$[]$a$::jsonb, $a$COMO NO CANTARTE SEÑOR.json$a$),
('e30fa89b-2d38-4549-9648-3c8efa0c3b40', $a$DESDE MI INTERIOR$a$, $a$MIL VECES TE FALLE MAS TU FUISTE ...$a$, $a$--$a$, $a$[{"paragraph": "MIL VECES TE FALLE MAS TU FUISTE FIEL  \n TU GRACIA ME LEVANTO  \n ME VASTA TU AMOR"}, {"paragraph": "DIOS ETERNO TU LUZ SIEMPRE BRILLARA  \n Y TU GLORIA INCOMPARABLE SIN FINAL"}, {"paragraph": "SEÑOR TU VOLUNTAD PERMANECERA \n EN TI ME QUIERO PERDER EN ADORACIÓN"}, {"paragraph": "Y DE MI CORAZÓN TE DOY EL CONTROL \n CONSUME TODO MI INTERIOR \n DIOS"}, {"paragraph": "JUSITICIA y amor me abrazan señor  \n te amo desde mi interior"}, {"paragraph": "/Dios eterno tu luz siempre brillara y tu gloria incomparable sin final  \n Y el clamor de mi ser contigo siempre estará \n desde mi interior mi alma clamara/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$DESDE MI INTERIOR.json$a$),
('b1658385-a7ff-40e5-8413-d6a937df11f3', $a$Consagrarme Todo Entero #462$a$, $a$CONSAGRARME TODO ENTERO   (#462)...$a$, $a$--$a$, $a$[{"paragraph": "CONSAGRARME TODO ENTERO \n (#462)"}, {"paragraph": "Consagrarme todo entero \n alma, vida y corazón, \n es el intimo deseo, \n que hoy me anima, buen Señor."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Al contrito has prometido  \n que de Ti no arrojarás, \n hoy propicio eres conmigo,  \n y tu Espíritu me das."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Confesando mis pecados,  \n que sin numero han de ser,  \n y arrojando todo a un lado,  \n a servirte aprenderé."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "Mi canción constante sea,  \n y mi sola inspiración,  \n proclamar la dicha entera,  \n del que vive para Dios."}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}, {"paragraph": "¡Oh, que gozo llena mi alma,  \n al pensar que suyo soy.  \n Y que pronto en las moradas,  \n estaré de mi Señor!"}, {"paragraph": "Héme aquí Señor \n a tus plantas hoy, \n pues a ti consagrar quiero,  \n todo lo que soy."}]$a$::jsonb, $a$[]$a$::jsonb, $a$Consagrarme Todo Entero.json$a$),
('3191fad4-5260-4aa2-ba9a-815872d0c93e', $a$HAY UNA SENDA n. 102$a$, $a$Hay una senda que el mundo no con...$a$, $a$--$a$, $a$[{"paragraph": "Hay una senda que el mundo no conoce \n Hay una senda que yo pude encontrar \n /En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar/"}, {"paragraph": "Hay una senda que el mundo no conoce \n Hay una senda que yo pude encontrar \n /En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar/"}, {"paragraph": "Solamente en Cristo, solamente en Él \n La salvación se encuentra en Él, \n No hay otro nombre dado a los hombres  \n Solamente en Cristo, solamente en Él."}, {"paragraph": "En cristo tengo la salvación de mi alma \n Cristo es la senda que me puede salvar En cristo tengo la salvación de mi alma \n Solamente en Cristo, solamente en Él."}, {"paragraph": "Cuan gloriosa será la mañana, \n Cuando venga Jesús el Salvador. \n Los salvados reunidos como hermanos, bienvenida daremos al Señor."}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}, {"paragraph": "Esperamos aquel día glorioso \n Para dar la bienvenida al Dios de amor, \n Donde todo será color de rosa \n En la santa fragancia del Señor."}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}, {"paragraph": "El cristiano fiel y verdadero,  \n Y también el obrero de valor, \n Y la iglesia, esposa del Cordero, \n Estarán en los brazos del Señor"}, {"paragraph": "No habrá necesidad, de la luz el resplandor. \n Ni el sol dará su luz, ni tampoco su calor. \n Allí llanto no habrá, ni tristeza ni dolor, \n Porque entonces Jesús el Rey del cielo,  \n Para siempre será consolador."}]$a$::jsonb, $a$[]$a$::jsonb, $a$HAY UNA SENDA n. 102.json$a$),
('25cbcbe3-95a7-4404-adb9-755cc9e911d1', $a$CANTARE DE TU AMOR$a$, $a$//POR MUCHO TIEMPO BUSQUÉ   UNA R...$a$, $a$--$a$, $a$[{"paragraph": "//POR MUCHO TIEMPO BUSQUÉ \n UNA RAZÓN DE VIVIR \n EN MEDIO DE MIL PREGUNTAS \n TU AMOR ME RESPONDIÓ"}, {"paragraph": "AHORA VEO LA LUZ \n Y YA NO TENGO TEMOR \n TU REINO VINO A MI VIDA \n Y AHORA VIVO PARA TI"}, {"paragraph": "CANTARÉ DE TU AMOR \n RENDIRÉ MI CORAZÓN ANTE TI \n TU SERÁS MI PASIÓN \n Y MIS PASOS SE GUIARAN POR TU VOZ \n MI JESÚS Y MI REY \n DE TU GRAN AMOR CANTARE//"}]$a$::jsonb, $a$[]$a$::jsonb, $a$CANTARE DE TU AMOR.json$a$),
('bb93f7c0-1e4c-0700-a4a7-234bbe290686', $a$HAY UN REDENTOR$a$, $a$Hay un redentor es Jesús Dios hijo Es mesías rey$a$, $a$C/D|Do-Re$a$, $a$[{"id": "46fb2b2c-3c25-5648-e19b-3e6df63bbb3e", "paragraph": "Hay un redentor\nes Jesús Dios hijo\nEs mesías rey cordero\nel santísimo.", "chorusPos": [[1]]}, {"id": "6dc19fa5-06a6-e8c9-cc5b-f610cd76d624", "paragraph": "Jesús me redime\nnombre sobre todos;\nÉL ha muerto por nosotros\npor la voluntad de Dios.", "chorusPos": [[1]]}, {"id": "7ac1710c-a549-9971-35da-cebfb0173a6f", "paragraph": "Cuando esté en la gloria\nyo veré su cara\nServiré a mi rey por siempre\nen lugar sagrado.", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Gracias Padre mío\npor darle a sufrir\nY dejar su Espíritu\ntu obra aquí para cumplir", "id": "d6730ae3-53da-95d0-24b9-dd040b8d4127"}, {"choir": "/ Gracias Padre mío\npor darle a sufrir\nY dejar su Espíritu\ntu obra aquí para cumplir /\n\nY dejar su Espíritu\ntu obra aquí para cumplir.", "id": "a37dbbda-8099-3530-736e-a9b8c487b968"}]$a$::jsonb, $a$HAY UN REDENTOR.json$a$),
('b8dddf38-1b53-4b79-862c-9b7c04f7fd32', $a$enviame señor$a$, $a$Envíame Señor, Envíame Señor   En...$a$, $a$--$a$, $a$[{"paragraph": "Envíame Señor, Envíame Señor \n Envíame, Señor a predicar \n Y dame tu poder \n Y dame tu poder, \n Y dame tu poder para guiar."}, {"paragraph": "Por sendas de salud \n Por sendas de salud \n Por sendas de salud al pecador \n Envíame, Señor, envíame Señor \n Envíame, Señor a predicar."}]$a$::jsonb, $a$[]$a$::jsonb, $a$enviame señor.json$a$),
('6ab3ab45-e1f5-4a34-8376-8139c79ccc3a', $a$A SU NOMBRE GLORIA$a$, $a$OH QUE BUENO    ES MI JESUS    QU...$a$, $a$--$a$, $a$[{"paragraph": "OH QUE BUENO  \n ES MI JESUS  \n QUE MURIO POR MI  \n EN LA CRUZ  \n MIS PECADOS PERDONO."}, {"paragraph": "/A SU NOMBRE GLORIA \n A SU NOMBRE GLORIA/"}, {"paragraph": "/MARAVILLOSO ES EL SEÑOR \n PODEROSO ES EL SEÑOR/"}, {"paragraph": "/DIOS ESTA PRESENTE  \n PIDAN LO QUE QUIERAN/"}]$a$::jsonb, $a$[]$a$::jsonb, $a$A SU NOMBRE GLORIA.json$a$),
('288e0074-a047-448e-91ea-23ba420ac8a5', $a$HAY LIBERTAD$a$, $a$Las cadenas de la muerte me quitó...$a$, $a$--$a$, $a$[{"paragraph": "Las cadenas de la muerte me quitó \n Para mí ya no hay condenación \n Hay libertad, libertad \n Siendo esclavo del pecado me libró \n En la cruz compró mi redención \n Y libertad, libertad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}, {"paragraph": "Yo proclamo al que en la cruz por mí murió \n Y cambió mi duro corazón \n Por libertad, libertad \n El poder de su evangelio me salvó \n Y no me avergüenzo del Señor \n Mi libertad, libertad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}, {"paragraph": "Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad \n Al que el Hijo hace libre \n Es libre en verdad"}, {"paragraph": "Rompió mis cadenas \n Me dio vida nueva \n Y al fondo del mar echó mi maldad \n Lavó mis pecados \n Y me ha perdonado \n Solo en el nombre de Jesús \n Hay libertad"}]$a$::jsonb, $a$[]$a$::jsonb, $a$HAY LIBERTAD.json$a$),
('d78585e4-cf40-99a9-0a49-efeca453dc32', $a$NOBLE SOSTÉN$a$, $a$Noble sostén de la esperanza mía Fuente bendita,$a$, $a$D|Re$a$, $a$[{"id": "94c39b89-7af2-0ca0-0cae-39e34eb005dd", "paragraph": "Noble sostén de la esperanza mía\nFuente bendita, de vida eterna\nTan solo el alma, que en tus fuerzas fía\nTiene paz, tiene paz.", "chorusPos": [[1]]}, {"id": "f1711d47-479b-d8b4-9a11-e7c4f896b736", "paragraph": "Dura es la lucha, difícil la carrera\nNunca en la lucha desmayar podré\nMi espíritu renuevas con la idea nueva\nDe vencer, de vencer.", "chorusPos": [[1]]}, {"id": "bbbadf30-00fe-acb3-238d-95008e6c2ed1", "paragraph": "Yo soy muy débil, pero en ti soy fuerte\nPues tú me dotas de tu gran poder\nSi tu estás conmigo ni a la misma muerte\nTemeré, no temeré", "chorusPos": [[2]]}]$a$::jsonb, $a$[{"choir": "Mi sostén es Jesús\nNunca en la lucha desmayar podré\nMi sostén es Jesús el Señor\nnunca en la lucha desmayar podré", "id": "7d72edf8-bad5-624e-10d8-802d9386a97b"}, {"choir": "Alelu., alelu.,\nnunca en la lucha desmayar podre\n\n/ Alelu., aleluya,\n/ nunca en la lucha desmayar podre / /", "id": "a4782d56-304a-3d78-07ea-c5272d19b2df"}]$a$::jsonb, $a$NOBLE SOSTÉN.json$a$),
('2657381b-c278-e242-e3bf-7adb10625dab', $a$SEÑOR TE NECESITO$a$, $a$Me postro hoy, ante ti Y quiero allí, yo descans$a$, $a$C|Do$a$, $a$[{"id": "99577a99-2fee-0d4d-7594-350da62e04e5", "paragraph": "Me postro hoy, ante ti\nY quiero allí, yo descansar\nSin ti señor desecho estoy\nMi corazón tu guiaras", "chorusPos": [[1]]}, {"id": "06687b0a-ca98-4ff3-19bb-9c81ca084d0b", "paragraph": "En mi pecar, tú gracia, es más\nDonde estás Tú, tú gracia está\nY donde estás, yo libre soy\nSantidad es Cristo en mí", "chorusPos": [[1]]}, {"id": "6c1f3732-1c3c-ca79-9e3b-1ef734ea1da7", "paragraph": "Enséñame a cantarte a ti\nAl venir la tentación\nCuando débil soy rendirme a ti\nMi Esperanza y Salvación", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "Oh Señor, te necesito\nen cada momento\nMi defensor\nMi redentor\nDios, te necesito", "id": "7a21ba2d-abe6-f6bc-5baf-7cde30792585"}]$a$::jsonb, $a$SEÑOR TE NECESITO.json$a$),
('ea0dea0f-c4b5-a2e0-73c3-f4a2c67c031d', $a$DE GLORIA EN GLORIA$a$, $a$/De gloria en gloria te veo, Cuanto más te conoz$a$, $a$D|Re$a$, $a$[{"id": "d2fe3ba3-3676-326c-49cd-5e8792bd29a2", "paragraph": "/De gloria en gloria te veo,\nCuanto más te conozco;\nquiero saber más de ti.\nMi Dios cuán buen alfarero,\nLevántame y transfórmame;\nMoldéame a tu imagen Señor./", "chorusPos": [[1]]}]$a$::jsonb, $a$[{"choir": "//Quiero ser más como tú,\nver la vida como tú\nSatúrame de tu espíritu\nY reflejar al mundo tu amor. //", "id": "d83bebbd-f995-76d3-edaf-ee4ce9e49b2c"}]$a$::jsonb, $a$De Gloria en Gloria.json$a$)
